export type BbpsBiller = typeof bbpsBillers.$inferSelect;
export type InsertBbpsBiller = z.infer<typeof insertBbpsBillerSchema>;
export type BbpsCustomerBill = typeof bbpsCustomerBills.$inferSelect;
