// Prospect Readiness Status - Gating for proposal generation
export const ProspectReadinessStatusEnum = z.enum([
  'INITIAL',                    // Just created, no data yet
  'HOLDINGS_IMPORTED',          // Holdings imported (CAS/manual)
  'RISK_PROFILE_COMPLETED',     // Risk questionnaire completed
  'TAX_PROFILE_COMPLETED',      // Tax profile saved
  'READY_FOR_PROPOSAL'          // All data complete, can generate proposal
]);
export type ProspectReadinessStatus = z.infer<typeof ProspectReadinessStatusEnum>;

export const prospectClients = pgTable("prospect_clients", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  
  // Agent relationship
  agentId: varchar("agent_id").references(() => users.id).notNull(),
  
  // Basic prospect info
  name: varchar("name").notNull(),
  email: varchar("email"),
  mobile: varchar("mobile"),
  pan: varchar("pan"),
  
  // Client type and risk profile
  clientType: varchar("client_type").default("individual"),
  indicativeRiskProfile: varchar("indicative_risk_profile"),
  
  // Lifecycle state machine
  state: varchar("state").notNull().default("prospect"), // prospect, onboarded, active_client
  
  // Proposal Readiness State Machine
  readinessStatus: varchar("readiness_status").notNull().default("INITIAL"), // INITIAL -> HOLDINGS_IMPORTED -> RISK_PROFILE_COMPLETED -> TAX_PROFILE_COMPLETED -> READY_FOR_PROPOSAL
  readinessStatusUpdatedAt: timestamp("readiness_status_updated_at"),
  
  // Investment Profile (for readiness tracking)
  investmentHorizon: varchar("investment_horizon"), // short/medium/long/very_long
  investmentGoals: varchar("investment_goals"), // primary goal
  
  // Tax Profile (for readiness tracking)
  taxProfile: jsonb("tax_profile").$type<{
    taxSlabCategory: string; // '0%' | '5%' | '10%' | '15%' | '20%' | '25%' | '30%'
    residencyStatus: string; // 'resident' | 'nri' | 'rnor'
    hasHuf: boolean;
    hasOtherIncome: boolean;
    completedAt: string;
  }>(),
  
  // Consent tracking
  portfolioFetchConsent: boolean("portfolio_fetch_consent").default(false),
  portfolioFetchConsentAt: timestamp("portfolio_fetch_consent_at"),
  advisoryConsent: boolean("advisory_consent").default(false),
  advisoryConsentAt: timestamp("advisory_consent_at"),
  
  // Fetched portfolio (from NSDL/CDSL via PAN)
  fetchedPortfolio: jsonb("fetched_portfolio").$type<{
    fetchedAt: string;
    source: string; // 'nsdl' | 'cdsl' | 'manual_upload' | 'pan_fetch'
    holdings: Array<{
      isin?: string;
      symbol?: string;
      name: string;
      productType: string;
      quantity: number;
      currentValue: number;
      purchaseValue?: number;
      purchaseDate?: string;
    }>;
    totalValue: number;
    assetAllocation: Record<string, number>;
  }>(),
  
  // Uploaded portfolio (PDF/Excel)
  uploadedPortfolio: jsonb("uploaded_portfolio").$type<{
    uploadedAt: string;
    fileName: string;
    fileType: string;
    parsedHoldings: Array<{
      name: string;
      productType: string;
      quantity: number;
      currentValue: number;
    }>;
    totalValue: number;
  }>(),
  
  // Current portfolio (canonical working copy for prospect wizard)
  currentPortfolio: jsonb("current_portfolio").$type<Array<{
    id?: string;
    name: string;
    isin?: string;
    symbol?: string;
    assetType: string;
    productType?: string; // Preserves original type (pms, aif, insurance, etc.)
    quantity: number;
    averageCost?: number;
    currentValue: number;
    currentNav?: number;
    investedValue?: number;
    unrealizedGain?: number;
    unrealizedGainPercent?: number;
    folioNumber?: string;
    broker?: string;
    confidenceScore?: number;
  }>>(),
  
  // AI Portfolio Analysis
  portfolioAnalysis: jsonb("portfolio_analysis").$type<{
    analyzedAt: string;
    assetAllocationBreakdown: Record<string, { value: number; percentage: number }>;
    concentrationRisk: {
      topHoldingConcentration: number;
      sectorConcentration: Record<string, number>;
      alerts: string[];
    };
    performanceVsBenchmark: {
      portfolioReturn: number;
      benchmarkReturn: number;
      alpha: number;
      period: string;
    };
    missingAssetClasses: string[];
    externalVsFintekpro: {
      externalPercentage: number;
      fintekproPercentage: number;
    };
    gapAnalysis: Array<{
      gap: string;
      severity: 'low' | 'medium' | 'high';
      recommendation: string;
    }>;
    overallScore: number;
    riskScore: number;
  }>(),
  
  // Conversion tracking
  convertedUserId: varchar("converted_user_id").references(() => users.id),
  convertedAt: timestamp("converted_at"),
  
  // Timestamps
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => [
  index("idx_prospect_clients_agent").on(table.agentId),
  index("idx_prospect_clients_state").on(table.state),
  index("idx_prospect_clients_pan").on(table.pan),
  index("idx_prospect_clients_readiness").on(table.readinessStatus),
]);

